import re

_STRIP = re.compile(r"[^A-Z0-9]")


def normalize_ref(text):
    return _STRIP.sub("", text.upper())


def days_apart(a, b):
    return abs((a - b).days)


def batch_key(ref):
    ref = ref.strip().upper()
    if "-" not in ref:
        return ""
    return ref.rsplit("-", 1)[0].strip()

